"use strict";(self.webpackChunkmy_docs=self.webpackChunkmy_docs||[]).push([[8521],{1539:n=>{n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"/\u51fd\u6570","metadata":{"permalink":"/function/\u51fd\u6570","source":"@site/function/\u51fd\u6570.md","title":"MATLAB \u51fd\u6570\u901f\u67e5\u624b\u518c","description":"\u6309\u529f\u80fd\u5206\u7c7b\u7684MATLAB\u51fd\u6570\u53c2\u8003\u6307\u5357","date":"2025-06-23T03:19:56.000Z","tags":[{"inline":true,"label":"MATLAB","permalink":"/function/tags/matlab"},{"inline":true,"label":"\u7f16\u7a0b\u53c2\u8003","permalink":"/function/tags/\u7f16\u7a0b\u53c2\u8003"}],"readingTime":1.54,"hasTruncateMarker":true,"authors":[],"frontMatter":{"title":"MATLAB \u51fd\u6570\u901f\u67e5\u624b\u518c","sidebar_label":"MATLAB \u51fd\u6570","description":"\u6309\u529f\u80fd\u5206\u7c7b\u7684MATLAB\u51fd\u6570\u53c2\u8003\u6307\u5357","tags":["MATLAB","\u7f16\u7a0b\u53c2\u8003"]},"unlisted":false},"content":"import FunctionCard from \'@site/src/components/FunctionCard\';\\r\\nimport Tabs from \'@theme/Tabs\';\\r\\nimport TabItem from \'@theme/TabItem\';\\r\\n\\r\\n\\r\\n\\r\\n\x3c!-- truncate --\x3e\\r\\n## 1. \u8bed\u8a00\u57fa\u7840\\r\\n\\r\\n<FunctionCard \\r\\n  title=\\"\u547d\u4ee4\u884c\u63a7\u5236\\"\\r\\n  functions={[\\r\\n    {name: \'clc\', desc: \'\u6e05\u7a7a\u547d\u4ee4\u884c\u7a97\u53e3\', example: \'clc\\\\n% \u6e05\u7a7a\u5f53\u524d\u7ec8\u7aef\u5185\u5bb9\'},\\r\\n    {name: \'format\', desc: \'\u8bbe\u7f6e\u8f93\u51fa\u663e\u793a\u683c\u5f0f\', example: \'format long\\\\n% \u6539\u4e3a\u957f\u7cbe\u5ea6\u663e\u793a\'},\\r\\n    {name: \'diary\', desc: \'\u8bb0\u5f55\u4f1a\u8bdd\u5230\u6587\u4ef6\', example: \'diary log.txt\\\\n% \u5f00\u59cb\u8bb0\u5f55\u5230\u6587\u4ef6\'}\\r\\n  ]}\\r\\n/>\\r\\n\\r\\n<FunctionCard \\r\\n  title=\\"\u5e2e\u52a9\u7cfb\u7edf\\"\\r\\n  functions={[\\r\\n    {name: \'doc\', desc: \'\u6253\u5f00\u51fd\u6570\u6587\u6863\u9875\', example: \'doc plot\\\\n% \u67e5\u770bplot\u51fd\u6570\u6587\u6863\'},\\r\\n    {name: \'help\', desc: \'\u547d\u4ee4\u884c\u5feb\u901f\u5e2e\u52a9\', example: \'help sprintf\\\\n% \u663e\u793a\u7b80\u8981\u7528\u6cd5\'}\\r\\n  ]}\\r\\n/>\\r\\n\\r\\n## 2. \u77e9\u9635\u4e0e\u6570\u7ec4\\r\\n\\r\\n### 2.1 \u521b\u5efa\u77e9\u9635\\r\\n```matlab\\r\\n% \u521b\u5efa3x3\u5355\u4f4d\u77e9\u9635\\r\\nA = eye(3); \\r\\n\\r\\n% \u751f\u6210\u5bf9\u89d2\u77e9\u9635\\r\\nB = diag([1 2 3]);\\r\\n\\r\\n% \u6c34\u5e73\u62fc\u63a5\u77e9\u9635\\r\\nC = horzcat(A, B);\\r\\n```\\r\\n\\r\\n### 2.2 \u77e9\u9635\u8fd0\u7b97\\r\\n| \u51fd\u6570        | \u8bf4\u660e                  | \u793a\u4f8b                     |\\r\\n|-------------|-----------------------|--------------------------|\\r\\n| `inv`       | \u77e9\u9635\u6c42\u9006              | `inv(A)`                 |\\r\\n| `eig`       | \u7279\u5f81\u503c\u5206\u89e3            | `[V,D] = eig(A)`         |\\r\\n| `norm`      | \u77e9\u9635/\u5411\u91cf\u8303\u6570         | `norm(A, \'fro\')`         |\\r\\n\\r\\n## 3. \u53ef\u89c6\u5316\u51fd\u6570\\r\\n\\r\\n<Tabs>\\r\\n<TabItem value=\\"2d\\" label=\\"\u4e8c\u7ef4\u7ed8\u56fe\\">\\r\\n\\r\\n```matlab\\r\\n% \u57fa\u7840\u6298\u7ebf\u56fe\\r\\nx = 0:0.1:2*pi;\\r\\nplot(x, sin(x), title(\'Sine Wave\');\\r\\n\\r\\n% \u6563\u70b9\u56fe\u77e9\u9635\\r\\nscatter(rand(100,1), rand(100,1));\\r\\n```\\r\\n\\r\\n</TabItem>\\r\\n<TabItem value=\\"3d\\" label=\\"\u4e09\u7ef4\u7ed8\u56fe\\">\\r\\n\\r\\n```matlab\\r\\n[X,Y] = meshgrid(-2:.2:2);\\r\\nZ = X .* exp(-X.^2 - Y.^2);\\r\\nsurf(X,Y,Z);\\r\\n```\\r\\n\\r\\n</TabItem>\\r\\n</Tabs>\\r\\n\\r\\n## 4. \u51fd\u6570\u901f\u67e5\u8868\\r\\n\\r\\n### \u6309\u9996\u5b57\u6bcd\u68c0\u7d22\\r\\n```matlab\\r\\n%% A\\r\\n% abs    - \u7edd\u5bf9\u503c\\r\\n% angle  - \u76f8\u4f4d\u89d2\\r\\n\\r\\n%% B\\r\\n% bar    - \u67f1\u72b6\u56fe\\r\\n% bessel - \u8d1d\u585e\u5c14\u51fd\u6570\\r\\n```\\r\\n\\r\\n---\\r\\n\\r\\n> \ud83d\udccc **\u4f7f\u7528\u63d0\u793a**\uff1a\\r\\n> 1. \u5728MATLAB\u547d\u4ee4\u884c\u8f93\u5165 `help \u51fd\u6570\u540d` \u83b7\u53d6\u8be6\u7ec6\u5e2e\u52a9\\r\\n> 2. \u6309 `Tab` \u952e\u53ef\u81ea\u52a8\u8865\u5168\u51fd\u6570\u540d\\r\\n> 3. \u4f7f\u7528 `which \u51fd\u6570\u540d` \u67e5\u770b\u51fd\u6570\u8def\u5f84\\r\\n\\r\\n> \ud83d\udd17 **\u6269\u5c55\u8d44\u6e90**\uff1a\\r\\n> - [MATLAB\u5b98\u65b9\u6587\u6863](https://mathworks.com/help/matlab/)\\r\\n> - [MATLAB\u793a\u4f8b\u5e93](https://mathworks.com/examples/)"}]}}')}}]);